-- DDL de hub_leads como em um site com hub_db_version 1.0.4 (extraído apenas da estrutura de um backup real; sem nenhum dado).
-- Não tem shared_contact_id. {prefix} é substituído pelo teste.
CREATE TABLE `{prefix}hub_leads` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `profile_type` varchar(50) COLLATE utf8mb4_unicode_520_ci NOT NULL DEFAULT '',
  `name` varchar(255) COLLATE utf8mb4_unicode_520_ci NOT NULL,
  `email` varchar(191) COLLATE utf8mb4_unicode_520_ci NOT NULL DEFAULT '',
  `phone` varchar(50) COLLATE utf8mb4_unicode_520_ci NOT NULL DEFAULT '',
  `status` varchar(50) COLLATE utf8mb4_unicode_520_ci NOT NULL DEFAULT 'novo',
  `stage` varchar(50) COLLATE utf8mb4_unicode_520_ci NOT NULL DEFAULT 'lead_inicial',
  `source` varchar(100) COLLATE utf8mb4_unicode_520_ci NOT NULL DEFAULT 'direto',
  `gclid` varchar(255) COLLATE utf8mb4_unicode_520_ci DEFAULT NULL,
  `gbraid` varchar(255) COLLATE utf8mb4_unicode_520_ci DEFAULT NULL,
  `wbraid` varchar(255) COLLATE utf8mb4_unicode_520_ci DEFAULT NULL,
  `fbclid` varchar(255) COLLATE utf8mb4_unicode_520_ci DEFAULT NULL,
  `utm_source` varchar(100) COLLATE utf8mb4_unicode_520_ci DEFAULT NULL,
  `utm_medium` varchar(100) COLLATE utf8mb4_unicode_520_ci DEFAULT NULL,
  `utm_campaign` varchar(100) COLLATE utf8mb4_unicode_520_ci DEFAULT NULL,
  `utm_content` varchar(100) COLLATE utf8mb4_unicode_520_ci DEFAULT NULL,
  `utm_term` varchar(100) COLLATE utf8mb4_unicode_520_ci DEFAULT NULL,
  `notes` text COLLATE utf8mb4_unicode_520_ci,
  `custom_data` longtext COLLATE utf8mb4_unicode_520_ci,
  `revenue_value` decimal(15,2) NOT NULL DEFAULT '0.00',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `first_touch_gclid` varchar(255) COLLATE utf8mb4_unicode_520_ci DEFAULT NULL,
  `first_touch_fbclid` varchar(255) COLLATE utf8mb4_unicode_520_ci DEFAULT NULL,
  `first_touch_utm_source` varchar(100) COLLATE utf8mb4_unicode_520_ci DEFAULT NULL,
  `first_touch_utm_medium` varchar(100) COLLATE utf8mb4_unicode_520_ci DEFAULT NULL,
  `first_touch_utm_campaign` varchar(100) COLLATE utf8mb4_unicode_520_ci DEFAULT NULL,
  `first_touch_utm_term` varchar(100) COLLATE utf8mb4_unicode_520_ci DEFAULT NULL,
  `first_touch_utm_content` varchar(100) COLLATE utf8mb4_unicode_520_ci DEFAULT NULL,
  `session_id` varchar(50) COLLATE utf8mb4_unicode_520_ci DEFAULT NULL,
  `external_referrer` text COLLATE utf8mb4_unicode_520_ci,
  `first_visit_datetime` datetime DEFAULT NULL,
  `landing_url` text COLLATE utf8mb4_unicode_520_ci,
  `landing_path` text COLLATE utf8mb4_unicode_520_ci,
  `landing_query` text COLLATE utf8mb4_unicode_520_ci,
  `conversion_page` text COLLATE utf8mb4_unicode_520_ci,
  `pageviews_count` int(11) NOT NULL DEFAULT '0',
  `time_to_conversion` int(11) NOT NULL DEFAULT '0',
  `user_agent` text COLLATE utf8mb4_unicode_520_ci,
  `device_type` varchar(50) COLLATE utf8mb4_unicode_520_ci DEFAULT NULL,
  `browser` varchar(50) COLLATE utf8mb4_unicode_520_ci DEFAULT NULL,
  `os` varchar(50) COLLATE utf8mb4_unicode_520_ci DEFAULT NULL,
  `ad_user_data_consent` varchar(20) COLLATE utf8mb4_unicode_520_ci NOT NULL DEFAULT 'UNKNOWN',
  `consent_source` varchar(50) COLLATE utf8mb4_unicode_520_ci DEFAULT NULL,
  `client_ip_address` varchar(50) COLLATE utf8mb4_unicode_520_ci DEFAULT NULL,
  `_fbp` varchar(255) COLLATE utf8mb4_unicode_520_ci DEFAULT NULL,
  `_fbc` varchar(255) COLLATE utf8mb4_unicode_520_ci DEFAULT NULL,
  `lost_reason` varchar(191) COLLATE utf8mb4_unicode_520_ci DEFAULT NULL,
  `lost_at` datetime DEFAULT NULL,
  `first_contact_at` datetime DEFAULT NULL,
  `attempts_count` int(11) NOT NULL DEFAULT '0',
  `pipeline_central_id` varchar(36) COLLATE utf8mb4_unicode_520_ci DEFAULT NULL,
  `pipeline_sync_status` varchar(30) COLLATE utf8mb4_unicode_520_ci NOT NULL DEFAULT 'pending',
  `pipeline_sync_error` text COLLATE utf8mb4_unicode_520_ci,
  `pipeline_synced_at` datetime DEFAULT NULL,
  `stage_updated_at` datetime DEFAULT NULL,
  `stage_source` varchar(30) COLLATE utf8mb4_unicode_520_ci DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `profile_type` (`profile_type`),
  KEY `status` (`status`),
  KEY `stage` (`stage`),
  KEY `email` (`email`),
  KEY `gclid` (`gclid`),
  KEY `pipeline_central` (`pipeline_central_id`),
  KEY `pipeline_status` (`pipeline_sync_status`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_520_ci;
